//Reset usedWorkPage, if it was 'pyTopCaseWork' and no other page is available on clipboard by same insKey
if("pyTopCaseWork".equals(usedWorkPage)){
      String insKey = tools.getParamValue("WorkObjectID");
      ClipboardPage coverPage = tools.findPage("pyWorkCover");
      ClipboardPage pyWorkPage = tools.findPage("pyWorkPage");   

      //Give preference to pyWorkPage if its available on clipboard by same insKey.
      if (pyWorkPage!=null && pega_rules_page.getPageHandle(pyWorkPage).equals(insKey)) {
	      usedWorkPage = "pyWorkPage";
        } 
      //Give preference to pyWorkCover if available on clipboard by same insKey, when pyWorkPage is not there.
      if (coverPage != null && pega_rules_page.getPageHandle(coverPage).equals(insKey)) {
	       usedWorkPage = "pyWorkCover";
       } 
	   else{
        usedWorkPage = "";
        isPageFound = false;
     }	     
	}
